const TACTICAL_ORDERS_60={free:{name:'Free Action',desc:'Control the companion normally.'},focus:{name:'Focus Fire',desc:'Aim and attack the marked/selected target. Gains a Boost against a marked target.'},cover:{name:'Use Cover',desc:'Take cover before attacking.'},flank:{name:'Flank',desc:'Shift position before attacking; useful for breaking up clustered fire lanes.'},guard:{name:'Guard PC',desc:'Spend the action protecting the player; +1 defense to the PC until the next round.'},support:{name:'Support Squad',desc:'Spend the action granting a Boost to the next ally and recover 1 strain from the most strained ally.'},fallback:{name:'Fallback / Overwatch',desc:'Move away from the target and enter Overwatch if possible.'}};
function terrainTemplate60(kind='combat'){
  let seed=[...String(kind)].reduce((n,c)=>n+c.charCodeAt(0),0),heavy=1+(seed%3),canPos=4+(seed%3),consolePos=1+((seed>>2)%3),hazPos=6+((seed>>3)%3);
  return Array.from({length:9},(_,pos)=>({pos,cover:[1,3,5,7].includes(pos)?1:0,object:null,hazard:false,spent:false})).map(t=>{if(t.pos===heavy||t.pos===8-heavy)t.cover=2;if(t.pos===canPos)t.object='canister';if(t.pos===consolePos)t.object='console';if(t.pos===hazPos)t.hazard=true;return t})
}
function ensureTactical60(C=S.combat){if(!C)return null;C.tactical60=C.tactical60||{};let T=C.tactical60;T.terrain=Array.isArray(T.terrain)&&T.terrain.length===9?T.terrain:terrainTemplate60(C.kind);T.orders=T.orders&&typeof T.orders==='object'?T.orders:{};T.markedTarget=T.markedTarget||null;T.markedUntil=Number.isFinite(T.markedUntil)?T.markedUntil:0;T.guardPcUntil=Number.isFinite(T.guardPcUntil)?T.guardPcUntil:0;T.notice=T.notice||'';return T}
