function markTarget60(){let C=S.combat,T=C?.turn,target=selectedEnemy();if(!C||!T||!target)return;if(!spendManeuver(1,`Mark ${target.name}`))return;let tc=ensureTactical60(C);tc.markedTarget=target.id;tc.markedUntil=C.round+1;cLog(`${actorById(T.actorId).name} marks ${target.name} for coordinated fire.`);renderCombat()}
